cat << 'EOF' > generate_html.py
import json

with open('/app/benchmark/source_data.json', 'r') as f:
    data = json.load(f)

# The data structures:
# data['digital_payment_penetration']['data'] -> year, region, penetration_pct
# data['traditional_bank_branches']['data'] -> year, region, branches_k
# data['neobank_users']['data'] -> year, region, users_m
# data['digital_bank_licenses']['data'] -> year, region, cumulative_licenses

html_template = f"""
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Fintech Disruption: Traditional vs Digital</title>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&family=JetBrains+Mono:wght@400;700&display=swap" rel="stylesheet">
  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
  <style>
    :root {{
      --font-body: 'DM Sans', system-ui, sans-serif;
      --font-mono: 'JetBrains Mono', monospace;

      --bg: #0b1120;
      --surface: #151e32;
      --border: rgba(255, 255, 255, 0.08);
      --text: #f1f5f9;
      --text-dim: #94a3b8;

      /* Color palette */
      --color-teal: #0891b2;
      --color-gold: #d4a73a;
      --color-coral: #e11d48;
      --color-indigo: #4f46e5;
      --color-sage: #65a30d;
      --color-slate: #64748b;
    }}

    * {{ box-sizing: border-box; margin: 0; padding: 0; }}

    body {{
      font-family: var(--font-body);
      background-color: var(--bg);
      color: var(--text);
      padding: 40px;
      width: 1920px;
      height: 1080px;
      display: flex;
      flex-direction: column;
      gap: 30px;
    }}

    header {{
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      border-bottom: 1px solid var(--border);
      padding-bottom: 20px;
    }}

    h1 {{
      font-size: 42px;
      font-weight: 700;
      letter-spacing: -0.02em;
      color: #ffffff;
    }}

    .subtitle {{
      font-family: var(--font-mono);
      font-size: 16px;
      color: var(--color-gold);
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }}

    .dashboard {{
      display: grid;
      grid-template-columns: 2fr 1fr;
      grid-template-rows: 1fr 1fr;
      gap: 30px;
      flex: 1;
    }}

    .panel {{
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 24px;
      display: flex;
